# Build the solution grid
# 9x11 grid, special row at index 6
# Non-1 values: col 1=2, col 3=8, col 7=8, col 9=2

rows = 9
cols = 11
special_row = 6

# Build output grid - all zeros initially
output = [[0 for _ in range(cols)] for _ in range(rows)]

# Fill the special row (row 6) with the original values
original_row = [1, 2, 1, 8, 1, 1, 1, 8, 1, 2, 1]
output[special_row] = original_row

# Find non-1 values in original row
special_cols = {}
for c, v in enumerate(original_row):
    if v != 1 and v != 0:
        special_cols[c] = v

# Calculate peak row
peak_row = special_row - 4  # 6 - 4 = 2

# Fill between peak and special row with propagated values
for r in range(peak_row, special_row):
    for c in special_cols:
        if r == peak_row:
            output[r][c] = special_cols[c]
        else:
            output[r][c] = 1

# Convert to string format for submission
def grid_to_string(grid):
    return '\n'.join([' '.join(map(str, row)) for row in grid])

result = grid_to_string(output)
print(result)
